import{_ as e,o as r,c as d,a3 as a}from"./chunks/framework.D1iekJsc.js";const f=JSON.parse('{"title":"FreeLLM 一覧","description":"awesome-freellm-apis / freellm.net 無料 LLM API まとめ：提供商一覧、Base URL、MiniTavern 記入と本マニュアル専页への互链。","frontmatter":{"title":"FreeLLM 一覧","description":"awesome-freellm-apis / freellm.net 無料 LLM API まとめ：提供商一覧、Base URL、MiniTavern 記入と本マニュアル専页への互链。","head":[["meta",{"name":"keywords","content":"酒場,AI酒場,MiniTavern,AI相棒,AI友達,AIローカルチャット,Silly Tavern,SillyTavern,スマホでSilly Tavern,Silly Tavernスマホ版,Silly Tavern Android,Silly Tavern iOS,AIロールプレイ,キャラクターカード,AIチャット,スマホAI,オフラインAI,AIストーリー,ローカルLLM,Ollama,LM Studio,ワールドブック,正規表現,BYOK,ユーザーガイド,マニュアル"}],["meta",{"property":"og:title","content":"FreeLLM 一覧 · MiniTavern Docs"}],["meta",{"property":"og:description","content":"awesome-freellm-apis / freellm.net 無料 LLM API まとめ：提供商一覧、Base URL、MiniTavern 記入と本マニュアル専页への互链。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/ja/free-cloud/freellm"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/ja/free-cloud/freellm"}]]},"headers":[],"relativePath":"ja/free-cloud/freellm.md","filePath":"ja/free-cloud/freellm.md","lastUpdated":1787224147000}'),o={name:"ja/free-cloud/freellm.md"};function l(n,t,i,s,h,p){return r(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="freellm-一覧" tabindex="-1">FreeLLM 一覧 <a class="header-anchor" href="#freellm-一覧" aria-label="Permalink to &quot;FreeLLM 一覧&quot;">​</a></h1><p>コミュニティ維持の<strong>無料 LLM API 一覧</strong>：<a href="https://github.com/open-free-llm-api/awesome-freellm-apis" target="_blank" rel="noreferrer">awesome-freellm-apis</a>（データは毎日 <a href="https://freellm.net" target="_blank" rel="noreferrer">freellm.net</a> から更新）。数十社・数百の無料モデルを収録し、クレジットカード／電話認証の要否、Base URL／Key 取得リンクも注記。</p><p>本ページは <strong>MiniTavern ユーザー向け要約</strong>：一覧でベンダーを選ぶ方法と、本マニュアルの専页・総覧との対応。<strong>モデル ID、限速、いま無料かは freellm.net／各社コンソールを正</strong>（倉庫 README に最近の更新日あり）。</p><h2 id="公式と入口" tabindex="-1">公式と入口 <a class="header-anchor" href="#公式と入口" aria-label="Permalink to &quot;公式と入口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>リソース</th><th>アドレス</th></tr></thead><tbody><tr><td>GitHub 倉庫</td><td><a href="https://github.com/open-free-llm-api/awesome-freellm-apis" target="_blank" rel="noreferrer">open-free-llm-api/awesome-freellm-apis</a></td></tr><tr><td>中国語 README</td><td><a href="https://github.com/open-free-llm-api/awesome-freellm-apis/blob/main/README.zh-CN.md" target="_blank" rel="noreferrer">README.zh-CN.md</a></td></tr><tr><td>オンライン</td><td><a href="https://freellm.net" target="_blank" rel="noreferrer">freellm.net</a>（閲覧 · Playground · 設定ジェネレーター）</td></tr><tr><td>API Key 一覧</td><td><a href="https://freellm.net/free-llm-api-keys/" target="_blank" rel="noreferrer">freellm.net/free-llm-api-keys</a></td></tr><tr><td>モデル比較</td><td><a href="https://freellm.net/compare/" target="_blank" rel="noreferrer">freellm.net/compare</a></td></tr></tbody></table><h2 id="使い方-minitavern-接続" tabindex="-1">使い方（MiniTavern 接続） <a class="header-anchor" href="#使い方-minitavern-接続" aria-label="Permalink to &quot;使い方（MiniTavern 接続）&quot;">​</a></h2><ol><li><a href="https://freellm.net" target="_blank" rel="noreferrer">freellm.net</a> または倉庫の「提供商一覧」から選ぶ：<strong>カード不要を優先</strong>（Groq、Gemini、智譜 Flash など）。</li><li>提供商の <strong>Get Key</strong> から登録し API Key をコピー。</li><li><strong>Base URL</strong> と <strong>Model ID</strong> を控える（倉庫 Quick Reference／Best Models 表）。</li><li>MiniTavern：<strong>設定 → モデル → モデル接続 → 新規</strong><ul><li>本マニュアルに専页／App プリセットがある（下表）→ 専页どおり記入。</li><li>なければ <strong>カスタム (OpenAI)</strong>、Base URL＋Key＋モデル ID → <strong>テスト</strong>。</li></ul></li></ol><p>一般手順は <a href="/ultra_guides/ja/manual/model-link">モデル接続</a>。ロールプレイは<strong>対話向け</strong>テキストモデル優先；コーディング Agent は長劇情に向かないことがある。</p><table tabindex="0"><thead><tr><th>項目</th><th>説明</th></tr></thead><tbody><tr><td>収録基準（公式）</td><td>明確な無料層（短期体験だけではない）、公開アクセス可、体験金は明記</td></tr><tr><td>データの鮮度</td><td>毎日自動更新；限速と名簿は変わる</td></tr><tr><td>本マニュアルとの関係</td><td>総覧と専页は「App での記入」；本ページ＋freellm.net は「他にどのベンダーを試せるか」</td></tr></tbody></table><h2 id="本マニュアルの専页-優先して読む" tabindex="-1">本マニュアルの専页（優先して読む） <a class="header-anchor" href="#本マニュアルの専页-優先して読む" aria-label="Permalink to &quot;本マニュアルの専页（優先して読む）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>提供商</th><th>マニュアル</th><th>App プラットフォーム</th></tr></thead><tbody><tr><td>Agnes AI</td><td><a href="/ultra_guides/ja/free-cloud/agnes-ai">Agnes AI</a></td><td>カスタム (OpenAI)／Images</td></tr><tr><td>OpenCode Zen</td><td><a href="/ultra_guides/ja/free-cloud/opencode-zen">OpenCode Zen</a></td><td>カスタム (OpenAI)</td></tr><tr><td>AIHubMix</td><td><a href="/ultra_guides/ja/free-cloud/aihubmix">AIHubMix</a></td><td>カスタム (OpenAI)／Images</td></tr><tr><td>OpenRouter</td><td><a href="/ultra_guides/ja/free-cloud/openrouter">OpenRouter</a></td><td>OpenRouter</td></tr><tr><td>智譜／硅基／百煉／DeepSeek／Gemini／Groq など</td><td><a href="/ultra_guides/ja/free-cloud/">無料クラウド総覧</a></td><td>総覧の各節</td></tr></tbody></table><h2 id="提供商一覧-永久無料層-·-要約" tabindex="-1">提供商一覧（永久無料層 · 要約） <a class="header-anchor" href="#提供商一覧-永久無料層-·-要約" aria-label="Permalink to &quot;提供商一覧（永久無料層 · 要約）&quot;">​</a></h2><p>倉庫「Permanent Free Tiers」からの抜粋（約 2026-08-20）。<strong>無料モデル数は変わる</strong>；完全表は <a href="https://github.com/open-free-llm-api/awesome-freellm-apis" target="_blank" rel="noreferrer">GitHub</a>／<a href="https://freellm.net" target="_blank" rel="noreferrer">freellm.net</a>。</p><table tabindex="0"><thead><tr><th>提供商</th><th>約無料モデル数</th><th>カード等</th><th>能力概要</th><th>Key</th></tr></thead><tbody><tr><td>NVIDIA NIM</td><td>125</td><td>電話認証</td><td>テキスト／図／動画／視覚など</td><td><a href="https://build.nvidia.com/settings/api-keys" target="_blank" rel="noreferrer">build.nvidia.com</a></td></tr><tr><td>ModelScope（魔搭）</td><td>56</td><td>登録</td><td>テキスト／図／動画／視覚</td><td><a href="https://modelscope.cn/my/myaccesstoken" target="_blank" rel="noreferrer">modelscope.cn</a></td></tr><tr><td>Cloudflare Workers AI</td><td>40</td><td>否</td><td>テキスト／図／コードなど</td><td><a href="https://dash.cloudflare.com/profile/api-tokens" target="_blank" rel="noreferrer">dash.cloudflare.com</a></td></tr><tr><td>Google Gemini</td><td>17</td><td>否</td><td>テキスト／マルチモーダル</td><td><a href="https://aistudio.google.com/app/apikey" target="_blank" rel="noreferrer">aistudio.google.com</a></td></tr><tr><td>GitHub Models</td><td>16</td><td>否</td><td>テキストなど</td><td><a href="https://github.com/marketplace/models" target="_blank" rel="noreferrer">GitHub Models</a></td></tr><tr><td>LLM7.io</td><td>16</td><td>否</td><td>テキスト／マルチモーダル</td><td><a href="https://token.llm7.io" target="_blank" rel="noreferrer">token.llm7.io</a></td></tr><tr><td>OVHcloud AI Endpoints</td><td>14</td><td>登録</td><td>テキストなど</td><td><a href="https://www.ovhcloud.com/en/public-cloud/ai-endpoints/catalog/" target="_blank" rel="noreferrer">ovhcloud.com</a></td></tr><tr><td>Ollama Cloud</td><td>13</td><td>登録</td><td>テキスト／視覚など</td><td><a href="https://ollama.com/settings/keys" target="_blank" rel="noreferrer">ollama.com/settings/keys</a></td></tr><tr><td>Groq</td><td>12</td><td>否</td><td>テキスト</td><td><a href="https://console.groq.com/keys" target="_blank" rel="noreferrer">console.groq.com/keys</a></td></tr><tr><td>Mistral AI</td><td>12</td><td>否</td><td>テキスト</td><td><a href="https://console.mistral.ai/api-keys" target="_blank" rel="noreferrer">console.mistral.ai</a></td></tr><tr><td>Cohere</td><td>12</td><td>否</td><td>テキスト</td><td><a href="https://dashboard.cohere.com/api-keys" target="_blank" rel="noreferrer">dashboard.cohere.com</a></td></tr><tr><td>Kilo Code</td><td>12</td><td>否</td><td>テキストなど</td><td><a href="https://kilo.ai" target="_blank" rel="noreferrer">kilo.ai</a></td></tr><tr><td>OpenCode Zen</td><td>11</td><td>登録</td><td><a href="/ultra_guides/ja/free-cloud/opencode-zen">専用ページ</a></td><td><a href="https://opencode.ai/auth" target="_blank" rel="noreferrer">opencode.ai/auth</a></td></tr><tr><td>Cerebras</td><td>8</td><td>否</td><td>テキスト</td><td><a href="https://cloud.cerebras.ai/" target="_blank" rel="noreferrer">cloud.cerebras.ai</a></td></tr><tr><td>Aion Labs</td><td>7</td><td>登録</td><td>テキスト（RP 向け含む）</td><td><a href="https://www.aionlabs.ai" target="_blank" rel="noreferrer">aionlabs.ai</a></td></tr><tr><td>Hugging Face</td><td>7</td><td>否</td><td>テキスト／コード</td><td><a href="https://huggingface.co/settings/tokens" target="_blank" rel="noreferrer">huggingface.co/settings/tokens</a></td></tr><tr><td>Agnes AI</td><td>5</td><td>登録</td><td><a href="/ultra_guides/ja/free-cloud/agnes-ai">専用ページ</a></td><td><a href="https://platform.agnes-ai.com/settings/apiKeys" target="_blank" rel="noreferrer">platform.agnes-ai.com</a></td></tr><tr><td>アリババ百煉（国際サイト等）</td><td>5</td><td>登録</td><td>総覧 <a href="/ultra_guides/ja/free-cloud/#通義千問--アリババクラウド百煉">通義</a></td><td><a href="https://bailian.console.aliyun.com/" target="_blank" rel="noreferrer">百煉コンソール</a></td></tr><tr><td>智譜 Z AI</td><td>4</td><td>否</td><td>総覧 <a href="/ultra_guides/ja/free-cloud/#智譜-ai-glm">智譜</a></td><td><a href="https://open.bigmodel.cn/usercenter/apikeys" target="_blank" rel="noreferrer">open.bigmodel.cn</a></td></tr><tr><td>SambaNova</td><td>4</td><td>登録</td><td>テキスト</td><td><a href="https://cloud.sambanova.ai/apis" target="_blank" rel="noreferrer">cloud.sambanova.ai</a></td></tr><tr><td>硅基流動</td><td>3</td><td>登録</td><td>総覧 <a href="/ultra_guides/ja/free-cloud/#siliconflow">硅基</a></td><td><a href="https://cloud.siliconflow.cn/account/ak" target="_blank" rel="noreferrer">cloud.siliconflow.cn</a></td></tr><tr><td>xAI／Grok</td><td>3</td><td>登録</td><td>テキスト（多くは贈金）</td><td><a href="https://console.x.ai" target="_blank" rel="noreferrer">console.x.ai</a></td></tr><tr><td>DeepSeek</td><td>2</td><td>登録</td><td>総覧 <a href="/ultra_guides/ja/free-cloud/#deepseek">DeepSeek</a></td><td><a href="https://platform.deepseek.com" target="_blank" rel="noreferrer">platform.deepseek.com</a></td></tr><tr><td>その他（Chutes、Glhf、AI21、Nscale、Nebius など）</td><td>少</td><td>多く登録</td><td>freellm 準拠</td><td>倉庫 Quick Reference</td></tr></tbody></table><h3 id="再生可能な無料枠" tabindex="-1">再生可能な無料枠 <a class="header-anchor" href="#再生可能な無料枠" aria-label="Permalink to &quot;再生可能な無料枠&quot;">​</a></h3><table tabindex="0"><thead><tr><th>提供商</th><th>説明</th><th>マニュアル</th></tr></thead><tbody><tr><td>OpenRouter</td><td><code>:free</code> プール；約 $10+ チャージで無料日リクエスト上限が上がる場合あり</td><td><a href="/ultra_guides/ja/free-cloud/openrouter">OpenRouter</a></td></tr></tbody></table><h2 id="クイック参照-·-base-url-と-app" tabindex="-1">クイック参照 · Base URL と App <a class="header-anchor" href="#クイック参照-·-base-url-と-app" aria-label="Permalink to &quot;クイック参照 · Base URL と App&quot;">​</a></h2><p>多くのベンダーは <strong>カスタム (OpenAI)</strong>。Gemini は App プリセット <strong>Gemini(Google)</strong> を使い、OpenAI Base URL を無理に当てはめない。</p><table tabindex="0"><thead><tr><th>提供商</th><th>Base URL（よくある）</th><th>App</th></tr></thead><tbody><tr><td>Groq</td><td><code>https://api.groq.com/openai/v1</code></td><td>カスタム (OpenAI)</td></tr><tr><td>硅基流動</td><td><code>https://api.siliconflow.cn/v1</code></td><td>カスタム (OpenAI)</td></tr><tr><td>智譜</td><td><code>https://open.bigmodel.cn/api/paas/v4</code></td><td>カスタム (OpenAI)</td></tr><tr><td>Agnes AI</td><td><code>https://apihub.agnes-ai.com/v1</code></td><td>カスタム (OpenAI)</td></tr><tr><td>OpenCode Zen</td><td><code>https://opencode.ai/zen/v1</code></td><td>カスタム (OpenAI)</td></tr><tr><td>OpenRouter</td><td><code>https://openrouter.ai/api/v1</code></td><td><strong>OpenRouter</strong></td></tr><tr><td>NVIDIA NIM</td><td><code>https://integrate.api.nvidia.com/v1</code></td><td>カスタム (OpenAI)</td></tr><tr><td>ModelScope</td><td><code>https://api-inference.modelscope.cn/v1</code></td><td>カスタム (OpenAI)</td></tr><tr><td>GitHub Models</td><td><code>https://models.github.ai/inference</code></td><td>カスタム (OpenAI)</td></tr><tr><td>Cerebras</td><td><code>https://api.cerebras.ai/v1</code></td><td>カスタム (OpenAI)</td></tr><tr><td>SambaNova</td><td><code>https://api.sambanova.ai/v1</code></td><td>カスタム (OpenAI)</td></tr><tr><td>Mistral</td><td><code>https://api.mistral.ai/v1</code></td><td>カスタム (OpenAI)</td></tr><tr><td>Hugging Face</td><td><code>https://router.huggingface.co/v1</code></td><td>カスタム (OpenAI)</td></tr><tr><td>LLM7.io</td><td><code>https://api.llm7.io/v1</code></td><td>カスタム (OpenAI)</td></tr><tr><td>Ollama Cloud</td><td><code>https://api.ollama.com</code>（ドキュメント準拠）</td><td>カスタム (OpenAI)</td></tr><tr><td>Gemini</td><td>プリセットで可</td><td><strong>Gemini(Google)</strong></td></tr><tr><td>DeepSeek</td><td>プリセットで可</td><td><strong>DeepSeek</strong></td></tr><tr><td>通義／百煉</td><td>プリセットで可</td><td><strong>Qwen</strong></td></tr></tbody></table><p>Cloudflare Workers AI の経路は <code>{account_id}</code> を含み設定が特殊；不慣れなら先に Groq／智譜／OpenRouter。</p><p>完全な Key リンクと「各社ベスト無料モデル」長表は倉庫 <a href="https://github.com/open-free-llm-api/awesome-freellm-apis/blob/main/README.zh-CN.md" target="_blank" rel="noreferrer">Best Free Models</a>。</p><h2 id="人気の無料モデル-倉庫の週用量例" tabindex="-1">人気の無料モデル（倉庫の週用量例） <a class="header-anchor" href="#人気の無料モデル-倉庫の週用量例" aria-label="Permalink to &quot;人気の無料モデル（倉庫の週用量例）&quot;">​</a></h2><p>「最近使われている」参考であり、<strong>ロールプレイ最適を意味しない</strong>：</p><table tabindex="0"><thead><tr><th>方向</th><th>例（freellm／広場 ID 準拠）</th></tr></thead><tbody><tr><td>集約無料プール</td><td>OpenRouter：<code>nvidia/nemotron-3-ultra-550b-a55b:free</code> など</td></tr><tr><td>高速推論</td><td>Groq：<code>llama-3.3-70b-versatile</code>、<code>moonshotai/kimi-k2-instruct</code></td></tr><tr><td>中国語対話</td><td>智譜 Flash、硅基無料タグモデル、百煉新規枠</td></tr><tr><td>マルチモーダルテキスト＋生図</td><td><a href="/ultra_guides/ja/free-cloud/agnes-ai">Agnes AI</a>、<a href="/ultra_guides/ja/free-cloud/aihubmix">AIHubMix</a></td></tr></tbody></table><h2 id="画像-動画" tabindex="-1">画像／動画 <a class="header-anchor" href="#画像-動画" aria-label="Permalink to &quot;画像／動画&quot;">​</a></h2><ul><li>一覧で複数が <code>image</code>／<code>video</code> modality；<strong>MiniTavern 画像生成</strong>は OpenAI Images 互換または App 対応プラットフォームが必要（<a href="/ultra_guides/ja/free-cloud/#無料の画像生成">無料の画像生成</a>）。</li><li>App に <strong>内蔵動画生成はない</strong>；動画モデルは公式能力の対照用。</li></ul><h2 id="関連章" tabindex="-1">関連章 <a class="header-anchor" href="#関連章" aria-label="Permalink to &quot;関連章&quot;">​</a></h2><ul><li><a href="/ultra_guides/ja/free-cloud/">無料クラウド総覧</a></li><li><a href="/ultra_guides/ja/free-cloud/agnes-ai">Agnes AI</a> · <a href="/ultra_guides/ja/free-cloud/opencode-zen">OpenCode Zen</a> · <a href="/ultra_guides/ja/free-cloud/aihubmix">AIHubMix</a> · <a href="/ultra_guides/ja/free-cloud/openrouter">OpenRouter</a></li><li><a href="/ultra_guides/ja/manual/model-link">モデル接続</a></li><li><a href="/ultra_guides/ja/manual/errors">エラー排錯</a></li></ul>',28)])])}const u=e(o,[["render",l]]);export{f as __pageData,u as default};
